COMMENT ON TABLE MATR_USR.ATTO_SCANSIONATO IS 'Tabella di tracciatura dell''ATTO SCANSIONATO.

Il primo PDF generato sulla DEFINISCI ATTO viene salvato come FLG_SCANSIONATO=''N'' per consentire download in più fasi.
Solo alla scasnsione reale dell''atto carteceo firmato dagli interessati verrà sostituito il PDF nella colonna DOCUMENTO ed posto DATA_SCANSIONE alla data effettiva nonchè FLG_SCANSIONATO = ''S''.
';

COMMENT ON COLUMN MATR_USR.ATTO_SCANSIONATO.ID_ATTO IS 'ID dell''atto scansionato.';

COMMENT ON COLUMN MATR_USR.ATTO_SCANSIONATO.DOCUMENTO IS 'Documento A3 
creato in fase di definizione atto e poi sostituito dall''atto scansionato (se sarà possibile). Ultima scansione eseguita';

COMMENT ON COLUMN MATR_USR.ATTO_SCANSIONATO.DATA_SCANSIONE IS 'Data ultima scansione eseguita.';

COMMENT ON COLUMN MATR_USR.ATTO_SCANSIONATO.FLG_SCANSIONATO IS 'Flag identifica se ATTO è stato scansionato altrimenti è solo il primo salvataggio del PDF in fase di DEFINISCI ATTO';

COMMENT ON COLUMN MATR_USR.ATTO_SCANSIONATO.DATA_INS IS 'Data prima inserimento del PDF durante la DEFINISCI';

COMMENT ON COLUMN MATR_USR.ATTO_SCANSIONATO.NOME_FILE IS 'Nome file del documento dell''atto A3';

COMMENT ON COLUMN MATR_USR.ATTO_SCANSIONATO.DOCUMENTO_CONFORME IS 'Documento dell''ATTO CONFORME in formato A4 per comunicazioni verso l''esterno';

COMMENT ON COLUMN MATR_USR.ATTO_SCANSIONATO.DOCUMENTO_TEST IS 'Documento di test per versioni formato A4 degli atti';



