CREATE OR REPLACE TRIGGER MATR_USR.ESPONENTE 
AFTER UPDATE ON ESPONENTE    REFERENCING FOR EACH ROW
DECLARE
  IN_ID_ATTO_DIVORZIO NUMBER;
--PRAGMA AUTONOMOUS_TRANSACTION;
  V_TESTO_ANNOTAZIONE   VARCHAR2(4000);
  L_SID VARCHAR2(100);
BEGIN
    IN_ID_ATTO_DIVORZIO := :NEW.ID_ESPONENTE;
SELECT sys_context('USERENV', 'SID') INTO L_SID  FROM DUAL;
GENERA_LOG(
:NEW.ID_ESPONENTE,
:NEW.ANNO,
:NEW.PARTE_SERIE,
:NEW.ESPONENTE,
:NEW.ID_STATO,
:NEW.ID_UTENTE,
:NEW.PRIMO_NUMERO_ATTO,
:NEW.NUMERO_ATTI, 
:NEW.AREA,
:OLD.PRIMO_ATTO_VALIDO,
:OLD.ID_STATO,
:OLD.ID_UTENTE,
:OLD.PRIMO_NUMERO_ATTO,
:OLD.NUMERO_ATTI,
L_SID ,
:OLD.DATA_INS,
:OLD.DATA_UPD
);
EXCEPTION WHEN OTHERS THEN
NULL;
END;
/


CREATE OR REPLACE TRIGGER MATR_USR.TRGUPD_ESPONENTE 
before update ON MATR_USR.ESPONENTE 
for each row
begin
  :NEW.DATA_UPD:=SYSTIMESTAMP;
end;
/


