COMMENT ON TABLE MATR_USR.CONF_TIPO_ATTI IS 'Per OP195: La pratica di DIVORZIO ITALIANO DA TRIBUNALE (modello 039) non genera un ATTO ma solo una pratica da elaborare da chiunque entri come Ufficio Divorzio (quindi autorizzato ad aprire relativa maschera per DIVORZI).
Per gestire il non filtraggio rispetto all''esponente attivo per l''operatore viene imposto PARTESERIE ''XX'' per il tipo di lavorazione da selezionare dalla UI SCELTA TIPOLOGIA ATTO.';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.SERIE IS 'Se assume XX deve bypassare filtro ESPONENTE ed essere ammissibile come lavorazione se ufficio abilitato per la maschera';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.AREA IS 'TUTTE - valido per tutte le AREE dello stato civile.
MATRIMONIO, NASCITE, etc.';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.TIPO_RITO IS 'Tipologia RITO per matrimoni';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.SOTTOAREA IS 'Sotto Area dello Stato Civile. Ex. DIVORZI';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.MASCHERA_UI IS 'Identificativo della MASCHERA UI da utilizzare per data entry';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.LABEL_UI IS 'Per tipizzare diverse casistiche di label nella medesima area';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.ID_MODELLO_ATTO IS 'Modello di default per template dell''ATTO';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.FLG_TRASCRIZIONE IS 'Identifica un lavorazione di trascrizione che richiede logica specifica sull''anteprima atto per stampa e comunicazioni';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.ATTO_DA IS 'Tipizza richiedente ATTO per cittadinanze - SINDACO/CONSOLATO. OPPURE CENSISCE ATTO CHE RICHIEDE CONFERMA/NON CONFERMA SOTTO DIVORZI.
Tipizza sorgente PRIVATO o PUBBLICO per DECESSI.';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.ID_VERBALE1 IS 'PRIMO VERBALE O ACCERTAMENTO PER LE CITTADINANZE - RIFERISCE IL TIPO DI MODELLO DA PRECOMPILARE PER ANTEPRIMA DEL VERBALE/ACCERTAMENTO';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.ID_VERBALE2 IS 'SECONDO VERBALE O ACCERTAMENTO PER LE CITTADINANZE - RIFERISCE IL TIPO DI MODELLO DA PRECOMPILARE PER ANTEPRIMA DEL VERBALE/ACCERTAMENTO';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.TIPIZZAZIONE_X_ANNOTAZIONI IS 'ADOPERATO PER PILOTARE FILTRI AGGIUNTIVI SULLE ANNOTAZIONI AUTOMATICHE.
NEL CASO DIVORZI PER IDENTIFICARE ATTO DI SEPARAZIONE DA DIVORZIO';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.ID_VERBALE3 IS 'TERZO VERBALE O ACCERTAMENTO PER LE CITTADINANZE - RIFERISCE IL TIPO DI MODELLO DA PRECOMPILARE PER ANTEPRIMA DEL VERBALE/ACCERTAMENTO';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.SOTTOTIPO_ATTO IS 'Sottotipologia di atto - discriminante per maschera di scelta tipologia atto. CONCATENAZIONE DI FLAG DISCRIMINATI.
|FLAG_UFFICIALE|FLAG_FIGLIO|FLAG_DICHIARANTE|

FLAG_UFFICIALE - OSPEDALE, PUBBLICO
FLAG_FIGLIO - LEGITTIMO, NATURALE, ABBANDONATO, RITROVATO
FLAG_DICHIARANTE - CITTADINO, PADRE, MADRE, GENITORI, DOTTORE';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.MIG_FLAG_ACTIVE IS 'Campo tecnico di Migrazione - determina il tipo di atto dal numero modello';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.FLG_SECONDO_ATTO IS 'Per cittadinanza indica il secondo atto creato nei modelli che prevedono 2 atti di Cittadinanza nel medesimo workflow. Pilota la ricerca atti e la scelta tipologia atti per il quale l''atto deve essere visto per la ricerca ma non per la creazione.';

COMMENT ON COLUMN MATR_USR.CONF_TIPO_ATTI.MIG_FLAG_GEMELLI IS 'Campo tecnico di Migrazione - determina il tipo di atto dal numero modello per i gemelli';



