CREATE OR REPLACE TRIGGER MATR_USR.TRG_PRATICA_PUBBL 
BEFORE INSERT ON MATR_USR.PUBBLICAZIONI FOR EACH ROW
DECLARE
    L_NUMERO  VARCHAR2(20);

  IN_AREA VARCHAR2(200);
  IN_ANNO NUMBER;
  IN_ID_CONF_TIPO_ATTO NUMBER;
  OUT_NUMPRATICA VARCHAR2(200);
  OUT_ERRMESG VARCHAR2(200);
BEGIN

    -- GENERA NUOVO IDENTIFICATIVO NUMERO PRATICA.
   IN_ANNO := TO_CHAR(SYSDATE, 'YYYY');
   IN_AREA :=   'MATRIMONI';
   IN_ID_CONF_TIPO_ATTO :=   PKG_PRATICA.G_PRATICA_PUBBLICAZIONI ; --PUBBLICAZIONI
  PKG_PRATICA.GET_NEXT_NUMPRATICA(
    IN_AREA => IN_AREA,
    IN_ANNO => IN_ANNO,
    IN_ID_CONF_TIPO_ATTO => IN_ID_CONF_TIPO_ATTO,
    OUT_NUMPRATICA => OUT_NUMPRATICA,
    OUT_ERRMESG => OUT_ERRMESG
  );
  L_NUMERO := OUT_NUMPRATICA;
    -- GENERA NUOVO IDENTIFICATIVO NUMERO PRATICA.
 --   SELECT SUBSTR('0000000000'||TO_CHAR(NVL(MAX(PRATICA.NUMERO),'0')+1),-10) INTO L_NUMERO FROM PRATICA WHERE PRATICA.ANNO=TO_CHAR(SYSDATE, 'YYYY');
  --  INSERT INTO MATR_USR.PRATICA (ANNO, NUMERO, TIPO) VALUES (TO_CHAR(SYSDATE, 'YYYY'), L_NUMERO, 'PUBBLICAZIONE');
    :NEW.ANNO_PRATICA:=TO_CHAR(SYSDATE, 'YYYY');

    :NEW.NUMERO_PRATICA:= L_NUMERO;

    :NEW.AREA :=  'MATRIMONI';
    --DBMS_OUTPUT.PUT_LINE(L_NUMERO);
END;
/


