CREATE TABLE MATR_USR.ANNOTAZIONE_ATTO
(
  ID_ATTO_MASTER              NUMBER,
  AREA                        VARCHAR2(50 BYTE) NOT NULL,
  TESTO_ANNOTAZIONE           VARCHAR2(4000 CHAR) NOT NULL,
  DATA_PROPOSTA               DATE,
  ID_UTENTE_LOG               NUMBER,
  ID_CONF_STATO               NUMBER            NOT NULL,
  ID_ATTO_TARGET              NUMBER,
  ID_ORIGINE_ANNOTAZIONE      NUMBER            NOT NULL,
  ID_TIPO_ATTO_ANNOTAZIONE    CHAR(1 BYTE)      NOT NULL,
  ID_TIPO_ANNOTAZIONE         NUMBER            NOT NULL,
  ID_MOTIVO_SCARTO            NUMBER,
  TESTO_MOTIVO_SCARTO         VARCHAR2(1000 BYTE),
  ID_FORMULA                  NUMBER            NOT NULL,
  ID                          NUMBER            DEFAULT "MATR_USR"."SEQ_ID_ANNOTAZIONI"."NEXTVAL" NOT NULL,
  TARGET_NUMERO_ATTO          VARCHAR2(20 BYTE),
  TARGET_PARTE                VARCHAR2(5 BYTE),
  TARGET_SERIE                VARCHAR2(10 BYTE),
  TARGET_ANNO                 NUMBER(4),
  TARGET_ESPONENTE            VARCHAR2(20 BYTE),
  TARGET_ID_ATTO_ANAG         NUMBER,
  DATA_INS                    TIMESTAMP(6)      DEFAULT SYSTIMESTAMP          NOT NULL,
  DATA_UPD                    TIMESTAMP(6)      DEFAULT SYSTIMESTAMP          NOT NULL,
  ID_ANNOTAZIONE_PADRE        NUMBER,
  DATA_STAMPA                 DATE,
  DATA_MODIFICA               DATE,
  DATA_SCARTO                 DATE,
  DATA_ETICHETTATURA          DATE,
  FLG_SCANSIONE_PRIORITA      VARCHAR2(1 BYTE),
  NOTE                        VARCHAR2(4000 BYTE),
  ID_UTENTE_ETICHETTATURA     NUMBER,
  ID_UTENTE_MODIFICA          NUMBER,
  ID_UTENTE_SCARTO            NUMBER,
  ID_UTENTE_STAMPA            NUMBER,
  FLG_ANNOTAZIONE_AGGIORNATA  CHAR(1 BYTE)
)
TABLESPACE ANAG_USR
RESULT_CACHE (MODE DEFAULT)
PCTUSED    0
PCTFREE    10
INITRANS   1
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
            FLASH_CACHE      DEFAULT
            CELL_FLASH_CACHE DEFAULT
           )
LOGGING 
NOCOMPRESS 
NOCACHE
NOPARALLEL
MONITORING;

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_ATTO_MASTER IS 'ID_ATTO da cui è scaturita l''annotazione. Potrebbe non esistere in caso di annotazione manuale sul target';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.TESTO_ANNOTAZIONE IS 'Vale anche per Testo libero per una annotazione contestuale (Origine Annotazione)
Deve contenere la formula dell''annotazione con i campi già rimappati';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.DATA_PROPOSTA IS 'DATA_PROPOSTA della annotazione';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_UTENTE_LOG IS 'utente che propone l''annotazione';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_ATTO_TARGET IS 'Atto su cui apporre l''annotazione - PER LE ANNOTAZIONI AUTOMATICHE SU ATTI DIPENDENTI POTREBBE NON ESSERE DISPONIBILE L''ATTO INFORMATIZZATO E QUINDI NULL.';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_ORIGINE_ANNOTAZIONE IS 'Orgine dell''annotazione. Non riportata in maschera Nuova Proposta - ma in ricerca si';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_TIPO_ATTO_ANNOTAZIONE IS 'Tipologia di ATTO a cui si applica l''annotazione - medesimi della SCANSIONE';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_TIPO_ANNOTAZIONE IS 'Tipologia di ANNOTAZIONE contestuale all''AREA selezionata';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_MOTIVO_SCARTO IS 'ID motivo di scarto';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.TESTO_MOTIVO_SCARTO IS 'Testo con motivo di scarto
';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_FORMULA IS 'Id riferimento della FORMULA di ANNOTAZIONE';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID IS 'Identificativo unico annotazione';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.TARGET_NUMERO_ATTO IS 'NUMERO ATTO TARGET - SE NON PRESENTE ID_ATTO_TARGET';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.TARGET_PARTE IS 'PARTE ATTO TARGET - SE NON PRESENTE ID_ATTO_TARGET';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.TARGET_SERIE IS 'SERIE ATTO TARGET - SE NON PRESENTE ID_ATTO_TARGET';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.TARGET_ANNO IS 'ANNO ATTO TARGET - SE NON PRESENTE ID_ATTO_TARGET';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.TARGET_ESPONENTE IS 'ESPONENTE ATTO TARGET- SE NON PRESENTE ID_ATTO_TARGET';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.TARGET_ID_ATTO_ANAG IS 'ID_ATTO ANAGRAFE sorgente dell''informazione riportata in assenza di ID_ATTO_TARGET di stato civile';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_ANNOTAZIONE_PADRE IS 'Eventuale dipendenza con una annotazione che va etichettata prima della corrente. Esempio annotazione su atto di matrimonio prima dell''annotazione sull''atto di nascita ove si riporta la data di annotazione della precedente.';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.DATA_STAMPA IS 'DATA_STAMPA Data in cui l''annotazione è stata stampata';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.DATA_MODIFICA IS 'DATA_MODIFICA Data in cui il testo della annotazione è stato modificato';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.DATA_SCARTO IS 'DATA_SCARTO Data in cui l''annotazione è stata scartata';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.DATA_ETICHETTATURA IS 'DATA_ETICHETTATURA Data in cui l''annotazione è stata ETICHETTATA';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.FLG_SCANSIONE_PRIORITA IS 'Annotazione prioritaria per richiesta scansione atto';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_UTENTE_ETICHETTATURA IS 'Utente che annota l''annotazione';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_UTENTE_MODIFICA IS 'Utente che modifica l''annotazione';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_UTENTE_SCARTO IS 'Utente che scarta l''annotazione';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.ID_UTENTE_STAMPA IS 'Utente che stampa l''annotazione';

COMMENT ON COLUMN MATR_USR.ANNOTAZIONE_ATTO.FLG_ANNOTAZIONE_AGGIORNATA IS 'quando S inidica, per le annotazioni che lo prevedono, che l''aggiornamento anagrafico è già stato correttamente effettuato.';



