CREATE OR REPLACE TRIGGER MATR_USR.TRG_PRATICA_ANNOTAZIONE_DIV 
AFTER UPDATE ON MATR_USR.ANNOTAZIONE_ATTO FOR EACH ROW
WHEN (
((NEW.ID_CONF_STATO = 4 AND NEW.DATA_ETICHETTATURA IS NOT NULL) OR NEW.ID_CONF_STATO = 3) AND NEW.ID_ORIGINE_ANNOTAZIONE = 2 AND NEW.AREA = 'MATRIMONI' AND NEW.ID_TIPO_ATTO_ANNOTAZIONE IN ( 'M','I')
      )
DECLARE

  IN_ID_ATTO_DIVORZIO NUMBER;
  IN_ID_CONF_STATO NUMBER;

BEGIN

    IN_ID_CONF_STATO := :NEW.ID_CONF_STATO;
    IN_ID_ATTO_DIVORZIO :=   :NEW.ID_ATTO_MASTER;
    IF (IN_ID_CONF_STATO = 4) THEN
        UPDATE MATR_USR.ATTO_DIVORZIO
        SET ID_STATO_AGGIORNAMENTO = (SELECT ID FROM MATR_USR.CONF_STATO_AGGIORNAMENTO WHERE DESCRIZIONE = 'Annotata'),
        DATA_UPD = SYSDATE
        WHERE ID_ATTO_DIVORZIO = IN_ID_ATTO_DIVORZIO;
    ELSIF (IN_ID_CONF_STATO = 3) THEN
        UPDATE MATR_USR.ATTO_DIVORZIO
        SET ID_STATO_AGGIORNAMENTO = (SELECT ID FROM MATR_USR.CONF_STATO_AGGIORNAMENTO WHERE DESCRIZIONE = 'Scartata'),
        DATA_UPD = SYSDATE
        WHERE ID_ATTO_DIVORZIO = IN_ID_ATTO_DIVORZIO;
    END IF;

END;
/


CREATE OR REPLACE TRIGGER MATR_USR.TRG_PRATICA_ANNOTAZIONE 
before UPDATE ON MATR_USR.ANNOTAZIONE_ATTO FOR EACH ROW
WHEN (
NEW.ID_CONF_STATO = 4  AND OLD.ID_CONF_STATO NOT IN (4) AND   NVL(NEW.ID_ATTO_MASTER,0) !=  NVL(NEW.ID_ATTO_TARGET,1) AND NEW.DATA_ETICHETTATURA IS NOT NULL
      )
DECLARE

  IN_ID  NUMBER;
   OUT_ERRMESG VARCHAR2(1000);
   OUT_ID NUMBER;
   IN_NOTA_AGGIUNTIVA   VARCHAR2(100) := NULL;
        IN_ID_COMUNE_INOLTRO NUMBER:= NULL;
            IN_ID_CONSOLATO_INOLTRO NUMBER:= NULL;
            IN_ALTRO_DESTINATARIO  VARCHAR2(100) := NULL;
            IN_EMAIL VARCHAR2(100) := NULL;
           IN_ID_UTENTE NUMBER := NULL; 
--SELECT * FROM ANNOTAZIONE_ATTO
BEGIN
    IN_ID :=   :NEW.ID;
    delete from GTT_ANNOTAZIONE_ATTO WHERE ID = IN_ID;
    INSERT INTO "MATR_USR"."GTT_ANNOTAZIONE_ATTO"
     (  
    "ID_ATTO_MASTER",
	"AREA",
	"TESTO_ANNOTAZIONE",
	"ID_UTENTE_LOG",
	"ID_ATTO_TARGET",
	"ID_FORMULA" ,
	"ID",
	"TARGET_NUMERO_ATTO" ,
	"TARGET_PARTE",
	"TARGET_SERIE",
	"TARGET_ANNO",
	"TARGET_ESPONENTE",
	"TARGET_ID_ATTO_ANAG",
    "DATA_ETICHETTATURA"
    )
    VALUES
    (
    :NEW.ID_ATTO_MASTER,
	:NEW.AREA,
	:NEW.TESTO_ANNOTAZIONE,
	:NEW.ID_UTENTE_LOG,
	:NEW.ID_ATTO_TARGET,
	:NEW.ID_FORMULA,
	IN_ID,
	:NEW.TARGET_NUMERO_ATTO,
	:NEW.TARGET_PARTE,
	:NEW.TARGET_SERIE,
	:NEW.TARGET_ANNO,
	:NEW.TARGET_ESPONENTE,
	:NEW.TARGET_ID_ATTO_ANAG,
    :NEW.DATA_ETICHETTATURA
    );


   PKG_ANNOTAZIONE.TRG_ANNOTA_COMUNIC(
    IN_ID => IN_ID,
    IN_ID_UTENTE  =>IN_ID_UTENTE,
    IN_NOTA_AGGIUNTIVA => IN_NOTA_AGGIUNTIVA,
    IN_ID_COMUNE_INOLTRO => IN_ID_COMUNE_INOLTRO,
    IN_ID_CONSOLATO_INOLTRO => IN_ID_CONSOLATO_INOLTRO,
    IN_ALTRO_DESTINATARIO => IN_ALTRO_DESTINATARIO,
    IN_EMAIL => IN_EMAIL,
    IN_ID_COMUNICA_OUT  => OUT_ID,
    OUT_ERRMESG => OUT_ERRMESG
  );
DBMS_OUTPUT.PUT_LINE('OUT_ERRMESG = ' || OUT_ERRMESG);


END;
/


CREATE OR REPLACE TRIGGER MATR_USR.TRG_RICHIESTA_SCANSIONE 
AFTER INSERT OR UPDATE OF ID_CONF_STATO ON MATR_USR.ANNOTAZIONE_ATTO FOR EACH ROW
WHEN (
NEW.ID_ORIGINE_ANNOTAZIONE IN (1, 2) OR OLD.ID_ORIGINE_ANNOTAZIONE IN (1, 2) AND NEW.ID_CONF_STATO IN (1, 3, 4)
      )
DECLARE -- SE L'ANNOTAZIONE E' DI TIPO AUTOMATICA O CONTESTUALE

BEGIN
	-- PER INSERT ED UPDATE FACCIAMO SEMPRE UNA INSERT SULLA CODA_SCANSIONE

	INSERT INTO CODA_SCANSIONE (ID_ANNOTAZIONE, ID_CONF_STATO_ANNOTAZIONE) VALUES (:NEW.ID, :NEW.ID_CONF_STATO);

	-- IN CASO DI CANCELLAZIONE DELL'ANNOTAZIONE DI ELIMINARE IL RECORD DALLA CODA SE NE OCCUPA IL JOB JAVA
END;
/


CREATE OR REPLACE TRIGGER MATR_USR.TRG_DIV_COMUNICAZIONE_AVV 
AFTER UPDATE ON MATR_USR.ANNOTAZIONE_ATTO FOR EACH ROW
WHEN (
NEW.ID_FORMULA = 190 AND NEW.ID_CONF_STATO = 4 
AND NEW.ID_ORIGINE_ANNOTAZIONE = 2 AND NEW.AREA = 'MATRIMONI' AND NEW.ID_TIPO_ATTO_ANNOTAZIONE IN ( 'M' )
      )
DECLARE
  IN_ID_ATTO_DIVORZIO NUMBER;
  V_TIPO_LANCIO VARCHAR2(200);
  OUT_ID_EMAIL_COMUNICAZIONE NUMBER;
  OUT_WARNING VARCHAR2(4000);
  OUT_ERROR VARCHAR2(4000);
  D_DATA_PROPOSTA         DATE;
  V_TESTO_ANNOTAZIONE   VARCHAR2(4000);
BEGIN
    IN_ID_ATTO_DIVORZIO := :NEW.ID_ATTO_MASTER;
    D_DATA_PROPOSTA := :NEW.DATA_PROPOSTA;
    V_TESTO_ANNOTAZIONE := :NEW.TESTO_ANNOTAZIONE;
    V_TIPO_LANCIO := 'TRIGGER';
    PKG_EMAIL_COMUNICAZIONI.INVIA_EMAIL_AVVOCATI_911_TRG(
    IN_ID_ATTO => IN_ID_ATTO_DIVORZIO,
    V_TIPO_LANCIO => V_TIPO_LANCIO,
    D_DATA_PROPOSTA => D_DATA_PROPOSTA,
    V_TESTO_ANNOTAZIONE => V_TESTO_ANNOTAZIONE,
    OUT_ID_EMAIL_COMUNICAZIONE => OUT_ID_EMAIL_COMUNICAZIONE,
    OUT_WARNING => OUT_WARNING,
    OUT_ERROR => OUT_ERROR
  );
END;
/


