COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.ID_ATTO IS 'Riferimento alla pratica per cui la comunicazione esiste. Mutuamente esclusivo con ID_PUBBLICAZIONE
';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.ALTRO_DESTINATARIO IS 'Altro destinatario (ex. Tribunale)';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.DATA_INVIO IS 'Data effettiva di invio della comunicazione - impostata dallo scodatore delle comunicazioni';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.MOTIVO_ERRORE IS 'Eventuale motivo di errore per STATO=''ERRORE''';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.NUMERO_PROTOCOLLO IS 'Numero di protocollazione GED.';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.ID_PUBBLICAZIONE IS 'Pubblicazione collegata in caso di Delega Nozze ad altro comune';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.DATA_INVIO_RICHIESTA IS 'Data di invio che può essere differita come per gli atti dopo 24h dalla richiesta - lo scodatore tiene conto di questa data';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.DATA_UPD IS 'Data ultimo aggiornamento';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.DATA_INS IS 'Data di creazione della comunicazione. Può differire dalla DATA di invio in caso di sospensione delle comunicazioni';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.FLAG_PROTOCOLLAZIONE IS 'S - da protocollare, N - non richiesta protocollazione';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.ID_RICH_PROTOCOLLAZIONE IS 'Eventuale ID della richiesta di protocollazione.';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.ANNO_PROTOCOLLO IS 'Anno del numero protocollo';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.ID_UFFICIO IS 'IDentificativo dell''Ufficio di RC potenziale destinatario della comunicazione';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.INFO_MITTENTE IS 'Informazioni sul mittente - ex. cittadino online';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.MESSAGGIO_INTESTAZIONE IS 'Intestazione del messaggio di comunicazione';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.FLG_AUTOMATICA IS 'Identifica comunicazioni inserite automaticamente (es. durante definizione atto). Deve consentire l''upsert su di esse nel caso di duplice definizione di un atto modificato.';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.ID_ANNOTAZIONE_PADRE IS 'ID annotazione da cui dipende per poter sbloccare l''invio della comunicazione. Atto da scansionare e annotazione da apporre.';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.FLG_PROCESSATA IS 'S: processata, indirizzo e data invio sono stati aggiornati; P: processata parzialmente, sono stati aggiornati gli indirizzi ma non la data invio';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.ID_UTENTE IS 'Utente di Anagrafe o Municipio che ha stipulato la cominicazione';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.TARGET_NUMERO_ATTO IS 'NUMERO ATTO TARGET - SE NON PRESENTE ID_ATTO_TARGET';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.TARGET_PARTE IS 'PARTE ATTO TARGET - SE NON PRESENTE ID_ATTO_TARGET';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.TARGET_SERIE IS 'SERIE ATTO TARGET - SE NON PRESENTE ID_ATTO_TARGET';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.TARGET_ANNO IS 'ANNO ATTO TARGET - SE NON PRESENTE ID_ATTO_TARGET';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.TARGET_ESPONENTE IS 'ESPONENTE ATTO TARGET- SE NON PRESENTE ID_ATTO_TARGET';

COMMENT ON COLUMN MATR_USR.COMUNICAZIONE.TARGET_ID_ATTO_ANAG IS 'ID_ATTO ANAGRAFE sorgente dell''informazione riportata in assenza di ID_ATTO_TARGET di stato civile';



