CREATE TABLE MATR_USR.ATTO_MATRIMONIO
(
  ID_ATTO_MATRIMONIO            NUMBER          NOT NULL,
  ID_SOGGETTO_SPOSO             NUMBER          NOT NULL,
  ID_SOGGETTO_SPOSA             NUMBER          NOT NULL,
  OPZIONALE1                    VARCHAR2(50 BYTE),
  OPZIONALE2                    VARCHAR2(50 BYTE),
  DATA_FORMAZIONE               DATE,
  ID_AUTORIZZAZIONE             NUMBER,
  ID_LIBRETTO                   NUMBER,
  ID_TIPO_RITO                  NUMBER,
  TESTO_LIBERO_MATR_RELIG       VARCHAR2(4000 BYTE),
  PARROCCHIA_CATT               VARCHAR2(100 BYTE),
  ID_TITOLO_CELEBRANTE_CATT     NUMBER,
  NOME_CELEBRANTE               VARCHAR2(100 BYTE),
  COGNOME_CELEBRANTE            VARCHAR2(100 BYTE),
  CHIESA                        VARCHAR2(100 BYTE),
  LUOGO_ACATT                   VARCHAR2(200 BYTE),
  OMISS_ID_COMUNE_TRIB          NUMBER,
  OMISS_ID_PROVINCIA_TRIB       NUMBER,
  OMISS_DATA_AUTORIZZ           DATE,
  FLG_SEPARAZIONE_BENI          CHAR(1 CHAR),
  DATA_SENTENZA_SEPARAZIONE     DATE,
  DATA_RICONCILIAZIONE          DATE,
  ID_CONF_TIPO_ACCORDO_SEPARAZ  NUMBER,
  FLG_TRASCR_ATTO_PLURILINGUE   CHAR(1 CHAR)    DEFAULT 'N',
  OPZIONALE3                    VARCHAR2(100 BYTE) DEFAULT NULL,
  DATA_CELEBRAZIONE             DATE,
  ID_TIPO_SEPARAZIONE_BENI      NUMBER,
  ID_USC_CELEBRANTE             NUMBER,
  DATA_INS                      TIMESTAMP(6)    DEFAULT SYSTIMESTAMP          NOT NULL,
  DATA_UPD                      TIMESTAMP(6)    DEFAULT SYSTIMESTAMP          NOT NULL,
  ID_SALA_CELEBRAZIONE          NUMBER,
  ID_COMUNE_CELEB               NUMBER,
  ID_RICHIESTA_RICEVUTA         NUMBER,
  ID_ATTO_MATR_ISCR             NUMBER,
  ID_ATTO_MATR_TRASCR           NUMBER,
  DATA_ANNOTA_SEPARAZIONE       DATE,
  OMISS_NUMERO_AUTORIZZ         VARCHAR2(50 BYTE),
  ID_COMUNE_SENTSEPAR           NUMBER,
  ID_PROVINCIA_SENTSEPAR        NUMBER,
  ID_STATO_CELEB                NUMBER,
  ID_PROVINCIA_CELEB            NUMBER,
  FLG_SOGGETTO_EXTREMIS         VARCHAR2(10 BYTE),
  CIVILE_DOC_RILASCIATODA       VARCHAR2(256 BYTE),
  CIVILE_DOC_DATARILASCIO       DATE,
  IMPEDIMENTO_CAUSA             VARCHAR2(256 BYTE),
  IMPEDIMENTO_SEGRETARIO        VARCHAR2(256 BYTE),
  CIVILE_DOC2_RILASCIATODA      VARCHAR2(256 BYTE),
  CIVILE_DOC2_DATARILASCIO      DATE,
  FLG_OMISS_PUBBLICAZIONI       CHAR(1 BYTE),
  ID_PUBBLICAZIONE_ISTAT        NUMBER,
  NOMINATIVO_CELEBRANTE         VARCHAR2(256 BYTE)
)
TABLESPACE ANAG_USR
RESULT_CACHE (MODE DEFAULT)
PCTUSED    0
PCTFREE    10
INITRANS   1
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
            FLASH_CACHE      DEFAULT
            CELL_FLASH_CACHE DEFAULT
           )
LOGGING 
NOCOMPRESS 
NOCACHE
NOPARALLEL
MONITORING;

