ALTER TABLE MATR_USR.ATTO_MATRIMONIO ADD (
  CONSTRAINT ATTI_MATRIMONIO_PRATICA_FK 
  FOREIGN KEY (ID_ATTO_MATRIMONIO) 
  REFERENCES MATR_USR.ATTO (ID_ATTO)
  ENABLE VALIDATE,
  CONSTRAINT ATTI_MATRIMONO_AUTORIZZA_FK 
  FOREIGN KEY (ID_AUTORIZZAZIONE) 
  REFERENCES MATR_USR.AUTORIZZAZIONI (ID_AUTORIZZ)
  ENABLE VALIDATE,
  CONSTRAINT ATTI_MATRIMONO_SOGGETTO_FK 
  FOREIGN KEY (ID_SOGGETTO_SPOSO) 
  REFERENCES MATR_USR.SOGGETTO (ID_SOGGETTO)
  ENABLE VALIDATE,
  CONSTRAINT ATTI_MATRIMONO_SOGGETTO_FKV1 
  FOREIGN KEY (ID_SOGGETTO_SPOSA) 
  REFERENCES MATR_USR.SOGGETTO (ID_SOGGETTO)
  ENABLE VALIDATE,
  CONSTRAINT ATTI_MATR_CONF_TIPO_ACC_SEP_FK 
  FOREIGN KEY (ID_CONF_TIPO_ACCORDO_SEPARAZ) 
  REFERENCES MATR_USR.CONF_TIPO_ACCORDO_SEPARAZIONI (ID_TIPO_ACCORDO)
  ENABLE VALIDATE,
  CONSTRAINT ATTI_MATR_CONF_TIPO_RITO_FK 
  FOREIGN KEY (ID_TIPO_RITO) 
  REFERENCES MATR_USR.CONF_TIPO_RITO_RELIGIOSO (ID_CONF_TIPO_RITI)
  ENABLE VALIDATE,
  CONSTRAINT ATTI_MATR_CONF_TITOLO_CELEB_FK 
  FOREIGN KEY (ID_TITOLO_CELEBRANTE_CATT) 
  REFERENCES MATR_USR.CONF_TITOLO_CELEBRANTI (ID_TITOLO_CELEBRANTE)
  ENABLE VALIDATE,
  CONSTRAINT ATTI_MATR_LIBRETTO_INTER_FK 
  FOREIGN KEY (ID_LIBRETTO) 
  REFERENCES MATR_USR.LIBRETTO_INTERNAZIONALE (ID_LIBRETTO_INTERNAZIONALE)
  ENABLE VALIDATE,
  CONSTRAINT ATTO_MATRIMONIO_FK1 
  FOREIGN KEY (ID_TIPO_SEPARAZIONE_BENI) 
  REFERENCES MATR_USR.CONF_TIPO_SEPARAZIONE_BENI (ID)
  ENABLE VALIDATE,
  CONSTRAINT ATTO_MATRIMONIO_FK2 
  FOREIGN KEY (ID_SALA_CELEBRAZIONE) 
  REFERENCES MATR_USR.CONF_TIPO_SALE (ID_SALA)
  ENABLE VALIDATE,
  CONSTRAINT ATTO_MATRIMONIO_FK3 
  FOREIGN KEY (ID_ATTO_MATR_ISCR) 
  REFERENCES MATR_USR.ATTO_CORRELATO (ID)
  ENABLE VALIDATE,
  CONSTRAINT ATTO_MATRIMONIO_FK4 
  FOREIGN KEY (ID_ATTO_MATR_TRASCR) 
  REFERENCES MATR_USR.ATTO_CORRELATO (ID)
  ENABLE VALIDATE,
  CONSTRAINT ATTO_MATRIMONIO_FK5 
  FOREIGN KEY (ID_PUBBLICAZIONE_ISTAT) 
  REFERENCES MATR_USR.PUBBLICAZIONI (ID_PUBBLICAZIONE)
  ENABLE VALIDATE,
  CONSTRAINT ATTO_MATRIMONIO_RICH_ALTRO_FK 
  FOREIGN KEY (ID_RICHIESTA_RICEVUTA) 
  REFERENCES MATR_USR.CONF_RICHIESTE_ALTRO_RICEVUTE (ID_CONF_RICHIESTA)
  ENABLE VALIDATE);
CREATE TABLE MATR_USR.ATTO
(
  ID_ATTO                     NUMBER            DEFAULT "MATR_USR"."SEQ_IDPRATICA_STATOCIVILE"."NEXTVAL" NOT NULL,
  ID_COMUNE_ISCRIZIONE        NUMBER,
  NUMERO_ATTO                 VARCHAR2(20 BYTE),
  ANNO                        NUMBER(4),
  PARTE                       VARCHAR2(5 BYTE),
  SERIE                       VARCHAR2(10 BYTE),
  VOLUME                      VARCHAR2(5 BYTE),
  UFFICIO                     VARCHAR2(50 BYTE),
  TRASCRITTO                  NUMBER            NOT NULL,
  TIPO_PROTOCOLLO             VARCHAR2(10 BYTE),
  NUMERO_PROTOCOLLO           NUMBER,
  ANNO_PROTOCOLLO             NUMBER(4),
  ANNO_PRATICA                NUMBER(4),
  ID_STATO_PRATICA            NUMBER,
  ID_TIPO_ATTO                INTEGER           NOT NULL,
  CODICE_TIPO_PROTOCOLLO      VARCHAR2(10 BYTE),
  ID_COMUNE_TRASCRIZIONE      NUMBER,
  ESPONENTE                   VARCHAR2(20 BYTE),
  DATA_INS_ATTO               TIMESTAMP(6)      DEFAULT SYSTIMESTAMP          NOT NULL,
  DATA_UPD_ATTO               TIMESTAMP(6)      DEFAULT SYSTIMESTAMP          NOT NULL,
  DATA_CANCELLAZIONE_ATTO     DATE,
  DATA_ANNULLAMENTO_ATTO      DATE,
  MOTIVO_ANNULLAMENTO_ATTO    VARCHAR2(500 BYTE),
  MOTIVO_CANCELLAZIONE_ATTO   VARCHAR2(500 BYTE),
  DATA_ATTO_TRASCRIZIONE      DATE,
  DATA_RILASCIO               DATE,
  ID_USC_TRASCRIZIONE         NUMBER,
  ID_UTENTE                   NUMBER            NOT NULL,
  ID_ORGANIZZAZIONE           NUMBER            NOT NULL,
  AREA                        VARCHAR2(50 BYTE) DEFAULT NULL NOT NULL,
  PARTE_SERIE                 VARCHAR2(15 BYTE) GENERATED ALWAYS AS ("PARTE"||"SERIE"),
  NUMESTESO_ATTO              VARCHAR2(97 BYTE) GENERATED ALWAYS AS (TO_CHAR("ANNO")||'/'||DECODE("PARTE"||"SERIE",'XX',"NUMERO_ATTO","PARTE"||"SERIE"||"ESPONENTE"||'/'||"NUMERO_ATTO")),
  OCCHIO_DOCUMENTO            CHAR(1 BYTE)      DEFAULT 'S'                   NOT NULL,
  ATTO_TRASCR_ANNO            NUMBER(4),
  ATTO_TRASCR_NUMEROATTO      VARCHAR2(20 BYTE),
  ATTO_TRASCR_PARTE           VARCHAR2(5 BYTE),
  ATTO_TRASCR_SERIE           VARCHAR2(10 BYTE),
  ATTO_TRASCR_DATA            DATE,
  ATTO_TRASCR_NOTA_UFFICIALE  VARCHAR2(4000 BYTE),
  DATA_PROTOCOLLO             DATE,
  ATTO_TRASCR_ESPONENTE       VARCHAR2(20 BYTE),
  DATA_PRATICA                DATE              DEFAULT SYSDATE               NOT NULL,
  NUMERO_PRATICA              VARCHAR2(20 BYTE),
  ATTO_TRASCR_DATAISCR        DATE,
  ATTO_TRASCR_DATAPROT_ISCR   DATE,
  ATTO_TRASCR_USC             VARCHAR2(100 BYTE),
  STEP_LAVORAZIONE            NUMBER            DEFAULT NULL,
  ID_LAVORAZIONE_PADRE        NUMBER,
  STEP_TABLAV                 CHAR(1 BYTE),
  FLG_RETTIFICA_INCORSO       CHAR(1 BYTE)      DEFAULT 'N',
  FLG_ATTO_TESTOLIBERO        CHAR(1 BYTE)      DEFAULT 'N',
  FLG_SPLIT_ATTO              CHAR(1 BYTE),
  DATA_DEFINIZIONE_ATTO       DATE,
  ATTO_TRASCR_NUMERO_ANSC     VARCHAR2(100 BYTE)
)
TABLESPACE ANAG_USR
RESULT_CACHE (MODE DEFAULT)
PCTUSED    0
PCTFREE    10
INITRANS   1
MAXTRANS   255
STORAGE    (
            INITIAL          64K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            BUFFER_POOL      DEFAULT
            FLASH_CACHE      DEFAULT
            CELL_FLASH_CACHE DEFAULT
           )
LOGGING 
NOCOMPRESS 
NOCACHE
NOPARALLEL
MONITORING;

COMMENT ON TABLE MATR_USR.ATTO IS 'La tabella contiene le informazioni rilevanti (es. anno, parte, serie, volume, ecc.) relative ad un atto di stato civile.';

COMMENT ON COLUMN MATR_USR.ATTO.ID_ATTO IS 'Campo che indica l''id dell''atto.';

COMMENT ON COLUMN MATR_USR.ATTO.ID_COMUNE_ISCRIZIONE IS 'ATTO TRASCRITTO: Indica il comune in cui si è registratp/iscritto l''atto originario';

COMMENT ON COLUMN MATR_USR.ATTO.NUMERO_ATTO IS 'Campo che indica il numero dell''atto. MAX 5 CIFRE';

COMMENT ON COLUMN MATR_USR.ATTO.ANNO IS 'Campo che indica l''anno in cui si registra l''atto.';

COMMENT ON COLUMN MATR_USR.ATTO.PARTE IS 'Campo che indica il numero della parte dell''atto.';

COMMENT ON COLUMN MATR_USR.ATTO.SERIE IS 'Campo che indica la serie dell''atto. Formato 3 CARATTERI: <LETTERA><ESPONENTE>';

COMMENT ON COLUMN MATR_USR.ATTO.VOLUME IS 'Campo che indica il volume dove si trova l''atto.';

COMMENT ON COLUMN MATR_USR.ATTO.UFFICIO IS 'Campo che indica l''ufficio in cui si registra l''atto.';

COMMENT ON COLUMN MATR_USR.ATTO.TRASCRITTO IS 'Flag che indica se l''atto è iscritto o trascritto.
0 se iscritto (originale), 1 se trascritto.';

COMMENT ON COLUMN MATR_USR.ATTO.TIPO_PROTOCOLLO IS 'Codice che identific univocamente l''ente protocollante dell''atto';

COMMENT ON COLUMN MATR_USR.ATTO.NUMERO_PROTOCOLLO IS 'Campo che indica il numero del protocollo.';

COMMENT ON COLUMN MATR_USR.ATTO.ANNO_PROTOCOLLO IS 'Campo che indica l''anno del protocollo.';

COMMENT ON COLUMN MATR_USR.ATTO.ANNO_PRATICA IS 'Campo che indica il l''anno della pratica.';

COMMENT ON COLUMN MATR_USR.ATTO.ID_STATO_PRATICA IS 'Campo che indica lo stato della pratica.';

COMMENT ON COLUMN MATR_USR.ATTO.ID_TIPO_ATTO IS 'Codice identificativo della tipologia di atto.';

COMMENT ON COLUMN MATR_USR.ATTO.CODICE_TIPO_PROTOCOLLO IS 'Codice identificativo dell''ente protocollante dell''atto.';

COMMENT ON COLUMN MATR_USR.ATTO.ID_COMUNE_TRASCRIZIONE IS 'ATTO_TRASCRITTO:  NON UTILIZZARE  - Comune dove è stato trascritto. POtenzialmente inutile da riportare';

COMMENT ON COLUMN MATR_USR.ATTO.ESPONENTE IS 'Campo che indica l''esponente dell''atto';

COMMENT ON COLUMN MATR_USR.ATTO.DATA_INS_ATTO IS 'DATA INSERIMENTO PRATICA';

COMMENT ON COLUMN MATR_USR.ATTO.DATA_UPD_ATTO IS 'Ultima data di aggiornamento';

COMMENT ON COLUMN MATR_USR.ATTO.DATA_CANCELLAZIONE_ATTO IS 'Data di cancellazione dell''atto';

COMMENT ON COLUMN MATR_USR.ATTO.DATA_ANNULLAMENTO_ATTO IS 'Data di annullamento dell''atto';

COMMENT ON COLUMN MATR_USR.ATTO.MOTIVO_ANNULLAMENTO_ATTO IS 'Motivo di annullamento dell''atto';

COMMENT ON COLUMN MATR_USR.ATTO.MOTIVO_CANCELLAZIONE_ATTO IS 'Motivo di cancellazione dell''atto';

COMMENT ON COLUMN MATR_USR.ATTO.DATA_ATTO_TRASCRIZIONE IS 'Data di trascrizione dell''ATTO';

COMMENT ON COLUMN MATR_USR.ATTO.DATA_RILASCIO IS 'Data di rilascio/iscrizione dell''ATTO 
Data Verbale (per verbali UNIONI CIVILI)';

COMMENT ON COLUMN MATR_USR.ATTO.ID_USC_TRASCRIZIONE IS 'Ufficiale di Stato Civile che ha trascritto l''atto';

COMMENT ON COLUMN MATR_USR.ATTO.ID_UTENTE IS 'Utente di Anagrafe o Municipio che ha stipulato l''atto';

COMMENT ON COLUMN MATR_USR.ATTO.ID_ORGANIZZAZIONE IS 'Organizzazione di appartenenza dell''utente che ha lavorato l''atto';

COMMENT ON COLUMN MATR_USR.ATTO.AREA IS 'AREA dello stato civile';

COMMENT ON COLUMN MATR_USR.ATTO.PARTE_SERIE IS 'Campo derivato da PARTE||SERIE';

COMMENT ON COLUMN MATR_USR.ATTO.NUMESTESO_ATTO IS 'Numero ATTO ESTESO (ANNO/PARTESERIEESPONENTE/NUMERO_ATTO)';

COMMENT ON COLUMN MATR_USR.ATTO.OCCHIO_DOCUMENTO IS 'Occhio del documento ATTO a [D]ESTRA o a [S]INISTRA (default).';

COMMENT ON COLUMN MATR_USR.ATTO.ATTO_TRASCR_ANNO IS 'ATTO TRASCRITTO: Campo che indica l''anno in cui si registra l''atto originario';

COMMENT ON COLUMN MATR_USR.ATTO.ATTO_TRASCR_NUMEROATTO IS 'ATTO TRASCRITTO: Campo che indica il numero dell''atto originario';

COMMENT ON COLUMN MATR_USR.ATTO.ATTO_TRASCR_PARTE IS 'ATTO TRASCRITTO: Campo che indica il numero della parte dell''atto originario.';

COMMENT ON COLUMN MATR_USR.ATTO.ATTO_TRASCR_SERIE IS 'ATTO TRASCRITTO: Campo che indica la serie dell''atto originario.';

COMMENT ON COLUMN MATR_USR.ATTO.ATTO_TRASCR_DATA IS 'OBSOLETO GIA PRESENTE ATTO_TRASCR_DATAISCR
 - 
ATTO TRASCRITTO: Data di Iscrizione dell''ATTO originario';

COMMENT ON COLUMN MATR_USR.ATTO.ATTO_TRASCR_NOTA_UFFICIALE IS 'ATTO_TRASCRITTO: Eventuale dettaglio relativo all''uffciale dell''atto iscritto/ Note su ATTO TRASCRITTO';

COMMENT ON COLUMN MATR_USR.ATTO.DATA_PROTOCOLLO IS 'Data protocollo dell''atto';

COMMENT ON COLUMN MATR_USR.ATTO.ATTO_TRASCR_ESPONENTE IS 'ATTO_TRASCRITTO: Eventuale Esponente relativo all''atto iscritto';

COMMENT ON COLUMN MATR_USR.ATTO.DATA_PRATICA IS 'Data prima accoglimento della Pratica/Inizio lavorazioni - differisce dalla data dell''Atto';

COMMENT ON COLUMN MATR_USR.ATTO.NUMERO_PRATICA IS 'Numero pratica di lavorazione - impostata come numero incrementale per ANNO_PRATICA';

COMMENT ON COLUMN MATR_USR.ATTO.ATTO_TRASCR_DATAISCR IS 'ATTO TRASCRITTO: Data di Iscrizione dell''ATTO originario';

COMMENT ON COLUMN MATR_USR.ATTO.ATTO_TRASCR_DATAPROT_ISCR IS 'ATTO TRASCRITTO: Data Protocollo di Iscrizione dell''ATTO originario';

COMMENT ON COLUMN MATR_USR.ATTO.ATTO_TRASCR_USC IS 'ATTO TRASCRITTO: USC che ha iscritto l''ATTO originario';

COMMENT ON COLUMN MATR_USR.ATTO.STEP_LAVORAZIONE IS 'Step corrente di lavorazione di un ATTO di CITTADINANZA. Utilizzato da Gestione ATTI di CITTADINANZA per capire da dove riprendere la lavorazione interrotta.
ASSUMERA'' 0 quando tutti gli STEP si saranno conclusi sull''ATTO DI PARTENZA
ASSUMERA'' VALORE n se ATTO di PARTENZA è allo step n e quindi sono stati creati ATTI clonati per gli step 1 a n-1 (con segno negativo sul loro rispettivo STEP_LAVORAZIONE).
ASSUMERA'' VALORE -n se ATTO clonato e creato per STEP n dell''ATTO di PARTENZA. puntato da ATTO_CITTADINANZA.ID_LAVORAZIONE_PADRE
ASSUMERA'' sempre NULL per ATTI/PRATICHE ove lo step lavorazione non viene preso in considerazione...Es. Non di cittadinanza.';

COMMENT ON COLUMN MATR_USR.ATTO.ID_LAVORAZIONE_PADRE IS 'CITTADINANZE: ID_ATTO dell''ATTO di PARTENZA nel caso di lavorazioni multistep come in CITTADINANZE. L''ATTO puntato dovrebbe essere sempre con STEP_LAVORAZIONE >=0. mentre quello corrente con STEP_LAVORAZIONE <0. 
DIVORZI: NEL CASO DI DIVORZI VIENE UTILIZZATO PER CENSIRE L''ATTO PADRE DI ACCORDO NEL CASO DI CONFERMA O MANCATA CONFERMA DELL''ACCORDO.
NASCITE: PRATICA DI RICHIESTA ATTO corrispondente a quella del primogenito. registrata in fase di DEFINIZIONE/splitting degli ATTI figli per singolo gemello. Per ogni GEMELLO/FIGLIO si produrrà un ATTO clone (OGNUNO CON PROPRIO ATTO_NASCITA_SOGGETTO) - CENSITO SOLO SUI SINGOLI ATTI FIGLI (escluso primogenito)';

COMMENT ON COLUMN MATR_USR.ATTO.STEP_TABLAV IS 'Numero del TAB ove riprendere nel caso di maschere di dataentry tra il verbale e l''atto';

COMMENT ON COLUMN MATR_USR.ATTO.FLG_RETTIFICA_INCORSO IS 'FLAG CHE IDENTIFICA SE UN ATTO IN CORSO DI RETTIFICA O SPLITTATO PRIMA DELL''ANTEPRIMA ATTO.
RETTIFICA: LO STATO DA "DEFINITO" RITORNA A "IN LAVORAZIONE". NEL CASO DI NASCITE VIENE UTILIZZATO PER BLOCCARE COMBO SUL NUMERO DI GEMELLLI.
SPLITTING: lO SPLITTING APPLICATO SULLA RIEPILOGO ATTO/PRATICA NON E'' ROLLBACKABILE.';

COMMENT ON COLUMN MATR_USR.ATTO.FLG_ATTO_TESTOLIBERO IS 'FLAG CHE IDENTIFICA SE L''ATTO E'' STATO GENERATO COME ATTO A TESTO LIBERO QUINDI L''ANTEPRIMA ATTO HA COMPORTAMENTO DIVERSO NELLA GENERAZIONE DEL FORMULARIO.ANCHE L''ID_TIPO_ATTO NON SARA'' SIGNIFICATIVO PER IL FORMULARIO CHE PRENDERA'' UN MODELLO DIVERSO PER L''ATTO LIBERO.';

COMMENT ON COLUMN MATR_USR.ATTO.FLG_SPLIT_ATTO IS 'Flag che identifica se è stato fatto lo split degli atti per atti gemellari';

COMMENT ON COLUMN MATR_USR.ATTO.DATA_DEFINIZIONE_ATTO IS 'Data DEFINIZIONE ATTO della Pratica ';



