CREATE OR REPLACE TRIGGER MATR_USR.TRG_PRATICA_ATTO 
BEFORE INSERT ON MATR_USR.ATTO FOR EACH ROW  --WHEN  (NEW.NUMERO_PRATICA is null)
DECLARE
    L_NUMERO  VARCHAR2(20);

  IN_AREA VARCHAR2(200);
  IN_ANNO NUMBER;
  IN_ID_CONF_TIPO_ATTO NUMBER;
  OUT_NUMPRATICA VARCHAR2(200);
  OUT_ERRMESG VARCHAR2(200);
BEGIN
    -- GENERA NUOVO IDENTIFICATIVO NUMERO PRATICA.
   IN_ANNO := TO_CHAR(SYSDATE, 'YYYY');
   IN_AREA :=   :NEW.AREA;
   IN_ID_CONF_TIPO_ATTO :=   :NEW.ID_TIPO_ATTO;
   IF  :NEW.NUMERO_PRATICA is null THEN 
        PKG_PRATICA.GET_NEXT_NUMPRATICA(
        IN_AREA => IN_AREA,
        IN_ANNO => IN_ANNO,
        IN_ID_CONF_TIPO_ATTO => IN_ID_CONF_TIPO_ATTO,
        OUT_NUMPRATICA => OUT_NUMPRATICA,
        OUT_ERRMESG => OUT_ERRMESG
        );
        L_NUMERO := OUT_NUMPRATICA;
        :NEW.NUMERO_PRATICA:= L_NUMERO ;
        :NEW.ANNO_PRATICA:=TO_CHAR(SYSDATE, 'YYYY');
  END IF;

   -- SELECT SUBSTR('0000000000'||TO_CHAR(NVL(MAX(PRATICA.NUMERO),'0')+1),-10) INTO L_NUMERO FROM PRATICA WHERE PRATICA.ANNO=TO_CHAR(SYSDATE, 'YYYY');
   -- INSERT INTO MATR_USR.PRATICA (ANNO, NUMERO, TIPO) VALUES (TO_CHAR(SYSDATE, 'YYYY'), L_NUMERO, 'ATTO');


    --DBMS_OUTPUT.PUT_LINE(L_NUMERO);
END;
/


CREATE OR REPLACE TRIGGER MATR_USR.TRG_PRATICA_ANNOTAZIONE_TEMP 
AFTER UPDATE ON MATR_USR.ATTO FOR EACH ROW
WHEN (
NEW.ID_STATO_PRATICA = 2 AND NEW.AREA='MATRIMONI' AND NEW.ID_TIPO_ATTO IN(131,132,134,135,136)
      )
DECLARE

  IN_ID_ATTO_DIVORZIO NUMBER;

BEGIN
    IN_ID_ATTO_DIVORZIO :=   :NEW.ID_ATTO;
    UPDATE  ATTO_DIVORZIO
    SET ID_STATO_AGGIORNAMENTO = (SELECT ID FROM CONF_STATO_AGGIORNAMENTO WHERE DESCRIZIONE = 'Annotata'),
    DATA_UPD = SYSDATE
    WHERE ID_STATO_AGGIORNAMENTO = 1
    AND ID_ATTO_DIVORZIO = IN_ID_ATTO_DIVORZIO;
END;
/


CREATE OR REPLACE TRIGGER MATR_USR.TRGUPD_ATTO 
before update ON MATR_USR.ATTO 
for each row
begin
  :NEW.DATA_UPD_ATTO:=SYSTIMESTAMP;
end;
/


ALTER TABLE MATR_USR.ATTO ADD (
  CONSTRAINT ATTO_PK
  PRIMARY KEY
  (ID_ATTO)
  USING INDEX MATR_USR.ATTO_PK
  ENABLE VALIDATE,
  CONSTRAINT ATTO_UK1
  UNIQUE (AREA, ANNO, PARTE_SERIE, NUMERO_ATTO)
  DISABLE NOVALIDATE,
  CONSTRAINT ATTO_UX1
  UNIQUE (CODICE_TIPO_PROTOCOLLO, ANNO_PROTOCOLLO, NUMERO_PROTOCOLLO)
  USING INDEX MATR_USR.ATTO_UX1
  ENABLE VALIDATE);

ALTER TABLE MATR_USR.ATTO ADD (
  CONSTRAINT ATTO_CONF_STATO_PRATICA_FK 
  FOREIGN KEY (ID_STATO_PRATICA) 
  REFERENCES MATR_USR.CONF_STATO_PRATICA (ID)
  ENABLE VALIDATE,
  CONSTRAINT ATTO_CONF_TIPO_ATTI_FK 
  FOREIGN KEY (ID_TIPO_ATTO) 
  REFERENCES MATR_USR.CONF_TIPO_ATTI (ID_CONF_TIPO_ATTO)
  DISABLE NOVALIDATE,
  CONSTRAINT ATTO_FK1 
  FOREIGN KEY (AREA) 
  REFERENCES MATR_USR.CONF_AREA_STATOCIVILE (AREA)
  ENABLE VALIDATE,
  CONSTRAINT ATTO_FK2 
  FOREIGN KEY (AREA, ANNO, PARTE_SERIE, ESPONENTE) 
  REFERENCES MATR_USR.ESPONENTE (AREA,ANNO,PARTE_SERIE,ESPONENTE)
  DISABLE NOVALIDATE,
  CONSTRAINT ATTO_FK3 
  FOREIGN KEY (NUMERO_PRATICA, ANNO_PRATICA, AREA) 
  REFERENCES MATR_USR.PRATICA (NUMERO,ANNO,AREA)
  ENABLE VALIDATE);

