COMMENT ON COLUMN MATR_USR.ATTO_DECESSO.DATA_PROTOCOLLO_PROC IS 'Data Protocollo del procedimento penale in caso di TipoATTO="Atto di More a Roma di Persona Sconosciuta o parti di cadavere"';

