COMMENT ON TABLE MATR_USR.ATTO_DIVORZIO IS 'Tabella per tracciatura ATTI di Divorzio e Separazioni
Lo stato di aggiornamento da evidenziato dall''aggiornamento anagrfico dello stato civile e dall''annotazione sull''atto di matrimonio';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_SOTTOTIPO_ATTO IS 'Sottotipo Atto utilizzato per le ricerche prenotazioni - Nullable perchè Da capire cosa inserire in caso di Tribunale';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_SOGGETTO1 IS 'Soggetto marito';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_SOGGETTO2 IS 'Soggetto moglie';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.NUMESTESO_ATTO_MATRIMONIO IS 'Numero esteso atto del matrimonio (<ANNO>/<PARTE>/<SERIE>/<NUMEROATTO>)';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.DATA_CELEBRAZIONE IS 'Data celebrazione del matrimonio';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_COMUNE_CELEBRAZIONE IS 'Comune celebrazione del matrimonio';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_TIPO_MATRIMONIO IS ' Tipologia di Matrimonio - CONF_TIPO_MATRIMONI';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.DATA_RICHIESTA IS 'Data richiesta del divorzio/separazione';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.NUMERO_PROTOCOLLO_RICH IS 'Numero protocollo della richiesta di divorzio/separazione';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_SOTTOTIPO_CONVENZIONE IS 'Sottotipo specifico per Tipologia di Convenzione (Art.6,Art.12,Tribunali)';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.DATA_STIPULA IS 'Data stipula convenzione';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_COMUNE_STIPULA IS 'Comune dove è stata stipulata la convenzione/ATTO';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.CONDIZIONI_DIVORZIO IS 'Condizioni di Divorzio ("Assenti","Presenti")';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_PROVV_TIPO IS 'Tipologia di Provvedimento dell''Autorità Giudiziaria. Art.6 e Art.12 (selettività sull''articolo)';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.TESTO_LIBERO IS 'Da valorizzare per Tipo Provvedimento = ALTRO';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_COMUNE_PROVV IS 'Comune emissione Provvedimento dell''Autorità Giudiziaria.(Art.6)/ Tribunale (Art.12) dove avvenuto atto di negoziazione assistita';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.DATA_PROVV IS 'Data emissione Provvedimento dell''Autorità Giudiziaria.Art.6/Art.12';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.NUMESTESO_ATTO_ACCORDO IS 'NUMERO ATTO DELL''ACCORDO DI SEPARAZIONE COMPOSTO <ANNO>/<PARTE>/<SERIE>/<NUMEROATTO> ';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_COMUNE_TRIB IS 'COMUNE  Tribunale (Art.12)';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.DATA_CONFERMA_ACCORDO IS ' Data conferma Accordo di divorzio e separazione consensuale';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.NUMESTESO_ATTO_CONFERMA_ACCORD IS 'NUMERO ATTO CONFERMA DELL''ACCORDO DI SEPARAZIONE CONTESTUALE COMPOSTO <ANNO>/<PARTE>/<SERIE>/<NUMEROATTO> ';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_SENTENZA IS 'Dettaglio sentenza per atto di divorzio/separazione - ATTO_DIVORZI_SENTENZA';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.IN_PENDENZA_GIUDIZIO IS 'Per Art.12 Accordo di Separazione - [NO], [PRESSO IL TRIBUNALE], [ALTRO]';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.FLAG_FIGLI_PRESENTI IS 'Presenza figli. (S - SI, N - NO)';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.DATA_APPUNTAMENTO IS 'Corrisponde alla data e orario dell''appuntamento fissato con la Gestione Appuntamento per secondo atto di conferma';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.RICHIESTO_ASSEGNO IS 'Se RICHIESTO ASSEGNO di mantenimento per sostegno economico. Per Art.12 Accordo di Separazione - [SI], [NO]';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_ACCORDO_DIVORZIO IS 'Tipologia di Accordo di Divorzio Art.12';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.FLAG_MEDESIMO_AVVOCATO IS 'Flag se utilizzato o meno medesimo avvocato (S - SI, N - NO)';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_AVVOCATO_1 IS 'Riferimento all''AVVOCATO in comune o del marito';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_AVVOCATO_2 IS 'Riferimento all''AVVOCATO della moglie';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_TIPO_MODIFICA_DIVORZIO IS ' TIPO DI MODIFICA RICHIESTA ALL''ACCORDO DI DIVORZIO/SEPARAZIONE ART.12';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.CORRISPONDENTE_RINUNCIATARIO IS '"Marito" o "Moglie" ASSUMONO IL RUOLO DI CORRISPONDENTE O RINUNCIATARIO A SECONDA DEL TIPO DI MODIFICA';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_CADENZA IS ' CADENZA PER L''ASSEGNO DI MANTENIMENTO';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.IMPORTO IS ' IMPORTO ASSEGNO';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.NOTA_MODIFICA IS ' TESTO LIBERO PER NOTA SULLA MODIFICA';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_COMUNE_ATTO_MATR IS 'Comune di iscrizione atto matrimonio';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.DATA_ACCORDO IS 'Data Accordo - preventiva alla conferma di accordo';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_COMUNE_TRIB_PEND_GIUD IS 'Comune Tribunale, se IN_PENDENZA_GIUDIZIO = PRESSO IL TRIBUNALE';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ALTRO_PENDENZA_GIUDIZIO IS 'Altro, se PENDENZA GIUDIZIO = ALTRO';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.CONIUGE_PRESENTE IS 'Per atti di CONFERMA/MANCATA CONFERMA accordo divorzio';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.FIGLI_PRESENTI IS 'NESSUNO; MAGGIORENNI; MINORENNI';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_ACCORDO_MODIFY_CONDIZIONI IS 'tipologia di accordo per atti di modifica delle condizioni di accordo di separazione o divorzio';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.FLAG_TIPO_ATTO_MATRIMONIO IS '"Flag che indica se l''atto è iscritto o trascritto.
0 se iscritto (originale), 1 se trascritto."';

COMMENT ON COLUMN MATR_USR.ATTO_DIVORZIO.ID_STATO_AGGIORNAMENTO IS 'Stato aggiornamento anagrafico';



