  FOREIGN KEY (ID_TIPO_MATRIMONIO) 
  REFERENCES MATR_USR.CONF_TIPO_MATRIMONI (ID_TIPO_MATRIMONIO)
  ENABLE VALIDATE,
  CONSTRAINT ATTO_DIVORZI_FK18 
  FOREIGN KEY (ID_ACCORDO_MODIFY_CONDIZIONI) 
  REFERENCES MATR_USR.CONF_TIPO_ACCORDO_MOD_COND (ID)
  ENABLE VALIDATE,
  CONSTRAINT ATTO_DIVORZI_FK19 
  FOREIGN KEY (ID_STATO_AGGIORNAMENTO) 
  REFERENCES MATR_USR.CONF_STATO_AGGIORNAMENTO (ID)
  ENABLE VALIDATE,
  CONSTRAINT ATTO_DIVORZI_FK3 
  FOREIGN KEY (ID_SOTTOTIPO_ATTO) 
