COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.MADRE_COGNOME IS 'MADRE - Cognome ';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.PADRE_NOME IS 'PADRE - Nome ';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.PADRE_COGNOME IS 'PADRE - Cognome ';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.ID_RICONOSCIMENTO_DA IS 'Tipo di riconoscimento di un figlio nato fuori dal matrimonio';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.ID_ISTITUTO_PENA_RICH IS 'Istituto di Pena richiedente';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.FLG_ISTITUTO_PENA IS 'Se richiessta da Istituto di Pena ';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.DATA_RICEZIONE_RICHIESTA IS 'Consenso sull''ATTO di Riconoscimento/Nascita - Data Ricezione Richiesta - Data protocollo (ricezione richiesta) di trascrizione atto di Decreto Variazione Cognome (modello 3I)';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.IN_QUALITA_DI IS 'Indicare in qualità di ("dichiarante" o "interessato")';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.TRASCR_DECRETO_EMESSO_DA IS 'Decreto emesso da (Prefetto, Ministero)';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.TRASCR_ID_COMUNE_PREFETTO_EMIT IS 'Comune del Prefetto emittente';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.TRASCR_ID_RICHIESTO_DA IS 'DEPRECATO DA RICHIESTA_TRASCRIZIONE NON USARE- Richiesto da';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.TRASCR_RICH_PERSFIS_AUTORITA IS 'DEPRECATO DA RICHIESTA_TRASCRIZIONE NON USARE- Richiesta da PersonaFisica o Autorità';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.TRASCR_ID_CONSOLATO IS 'DEPRECATO DA RICHIESTA_TRASCRIZIONE NON USARE- Richiesto da Consolato';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.TRASCR_ID_STATO_ESTERO IS 'DEPRECATO DA RICHIESTA_TRASCRIZIONE NON USARE- Stato del richiedente';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.DIR_ISTITUTO_COGNOME IS 'Direttore Istituto - Cognome';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.DIR_ISTITUTO_NOME IS 'Direttore Istituto - Nome';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.ISTITUTO_NOME IS 'Nome Istituto';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.TESTO_CAPPELLO_ATTO IS 'DEPRECATO DA ATTO_EXTENDED- Testo del cappello dell''atto';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.TESTO_CHIUSURA_ATTO IS 'DEPRECATO DA ATTO_EXTENDED - Testo della chiusura dell''atto';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.FLG_CAPPELLO IS 'DEPRECATO DA ATTO_EXTENDED - Flag Cappello prevalorizzato';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.FLG_CHIUSURA IS 'DEPRECATO DA ATTO_EXTENDED - Flag Chiusura prevalorizzata';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.TESTO_CORPO1_ATTO IS 'DEPRECATO DA ATTO_EXTENDED - Testo per la prima parte del corpo dell''atto libero';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.TESTO_CORPO2_ATTO IS 'DEPRECATO DA ATTO_EXTENDED - Testo per la seconda parte del corpo dell''atto libero';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.ID_SOGGETTO_DEFINITO IS 'In fase di DEFINIZIONE dell''ATTO conterrà l''ID_SOGGETTO creato e clonato (da anagrafe) su STATO_CIVILE. nel caso di nascituri per il quale non ho un soggetto a priori';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.FLG_PARTO_PLURIMO IS 'Flag che segnala se il PARTO è stato plurimo o meno. default a NULL fino allo splitting. se vi sono più figli viene impostato a ''S'' altrimenti a ''N''';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.ID_DICHIARANTE IS 'Tipologia di dichiarante per tipizzare il sottotipo di ATTO di NASCITA nonchÃ¨ modello da utilizzare per il formulario';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.FLG_ART_35_36 IS 'Check Box Art. 35-36 a comparsa sulle maschere dichiarazioni e trascrizioni in caso di genitori entrambi non ITALIANI.
Valori ammessi:
 0 o Null -  default non selezionato
 1 – applicazione art 35-36 (i genitori stranieri si avvalgono della propria legge nazionale per la scelta del cognome)
 2 – doppio cognome (cognome padre + cognome madre)
 3 – “libero” (editabile dall’ufficiale di stato civile) 
';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.FLG_COMUNICAZIONE IS 'Flag che segnala se una comunicazione è scritta ''S'' o verbale ''V''';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.ID_ATTO_PRERICON_PADRE IS 'ID_ATTO_CORRELATO per atto di prericonoscimento padre';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.ID_ATTO_PRERICON_MADRE IS 'ID_ATTO_CORRELATO per atto di prericonoscimento madre';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.FLG_DICH_TARDIVA IS 'Dichiarazione Tardiva ([S]i o [N]o) - se iscrizione da Pubblico Ufficiale';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.MOTIVO_DICH_TARDIVA IS 'Motivo della dichiarazione tardiva';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.DT_MOTIVO_RITARDO IS 'tipo del motivo del ritardo Tribunale-Altro';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.DT_TRIBUNALE_COMUNE IS 'Identificativo del comune del tribunale';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.DT_NUMERO_PROVVEDIMENTO IS 'numero provvedimento del Tribunale per dichiarazione tardiva';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.RICON_FLG_ASSENSO_FIGLIO IS 'Assenso del figlio al riconoscimento';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.FLG_MAGGIORE_SCEGLIECOGNOME IS 'Figlio Maggiorenne sceglie Cognome';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.FLG_ART33 IS 'Art.33';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.ID_CHECKBOX_COGNOME IS 'Scelta sul Cognome (1. Mantiene Cognome, 2. Aggiunge Cognome, 3. Sostituisce Cognome, 4. Antepone Cognome)';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.FLG_DISCONOSCIMENTO IS 'Disconoscimento';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.DATA_DECRETO_TRIBUNALE IS 'Data decreto emmesso dal tribunale per il cognome del riconosciuto nei casi di figli incestuosi';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.INC_NUMERO_PROVV_TRIBUNALE IS 'Numero provvedimento decreto emmesso dal tribunale per il cognome del riconosciuto nei casi di figli incestuosi';

