COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.COGNOME_NUOVO IS 'Cognome Nuovo per riconoscimenti';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.SCELTA_TRIBUNALE IS 'Scelta decreto emmesso dal tribunale per il cognome del riconosciuto nei casi di figli incestuosi';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA.ID_ATTO_CONSENSO_RICON IS 'ID_ATTO_CORRELATO per atto di consenso al riconoscimento o di consenso al prericonoscimento';

