COMMENT ON TABLE MATR_USR.ATTO_NASCITA_SOGGETTO IS 'Tabella per tracciatura Singoli neonati in caso di parti gemellari';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID IS 'ID del DETTAGLIO NASCITURO che in caso di DEFINISCI ATTO e pratica plurigemellare, costituirà il nuovo ID_ATTO dell''atto clonato per ogni singolo gemello, senza staccare altra sequence';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_ATTO_NASCITA IS 'Alla definisci atto per un Gemello non primogenito switcherà sul nuovo atto con ID_ATTO_NASCITA= ID';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.COGNOME IS 'Cognome del neonato';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.NOME IS 'Nome del neonato';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.DATAORARIO_NASCITA IS 'Data e orario del neonato';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.SESSO IS 'Sesso del neonato';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_COMUNE_NASCITA IS 'ID del Comune di Nascita';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.FLG_IMPOSTA_NOME_COGNOME IS 'Flag Imposta Cognome e Nome ([S]i o [N]o)- Art.38 Abbandoni';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_ATTO_CORRENTE IS 'Riferimento per ATTO CORRENTE';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_ATTO_ESTERO IS 'Riferimento per ATTO ESTERO';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_ATTO_RICON IS 'Riferimento per Assenso/Consenso sull''ATTO di Riconoscimento';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_ATTO_PRERICON IS 'Riferimento per Assenso/Consenso sull''ATTO di PreRicon';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_ATTO_NASCITA_CORR IS 'Riferimento all''ATTO di nascita per l''adozione/o correlato per altre operazioni';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_ATTO_ADOZIONE IS 'Riferimento all''ATTO di Adozione per la revoca';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_ATTO_MATRIMONIO IS 'Riferimento all''ATTO di MAtrimonio per il cambio di cognome';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.FLG_NATO_MORTO IS 'Nato Morto ([S]i o [N]o) - se iscrizione da Pubblico Ufficiale';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.FLG_INCESTUOSO IS 'DEPRECATO; SPOSTATO SU ATTO_NASCITA - Bambino incestuoso ([S]i o [N]o)- se iscrizione da Pubblico Ufficiale';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.FLG_MORTO_PREDENUNCIA IS 'Morto prima della denuncia ([S]i o [N]o)- se iscrizione da Pubblico Ufficiale';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.FLG_LUOGONASCITA_DIVERSO IS 'Luogo di Nascita Diverso ([S]i o [N]o)- se iscrizione da Pubblico Ufficiale';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.FLG_FUORI_OSPEDALE IS 'Nascita Fuori Ospedale ([S]i o [N]o)- se iscrizione da Pubblico Ufficiale';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.DATAORARIO_DENUNCIA_DAOSPEDALE IS 'Data e ORario Denuncia - per trascrizione da Ospedale';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.DATA_PROTOCOLLO_DAOSPEDALE IS 'Data Protocollo - per trascrizione da Ospedale';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.DATA_CERTIFICATO IS 'Data Certificato - se iscrizione da Pubblico Ufficiale';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.NOMINATIVO_DOTTORE IS 'Nominativo dottore/medico curante';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_OSPEDALE IS 'ID Ospedale di nascita';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_DICH_NATO_IN_MATRIMONIO IS 'DEPRECATO - Dichiarante in caso di figlio nato in costanza di matrimonio - o per gemelli';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_DICH_NATO_FUORI_MATRIMONIO IS 'DEPRECATO - Dichiarante in caso di figlio nato fuori matrimonio';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ISTITUTO_AFFIDAMENTO IS 'Istituto di affidamento - Figlio abbandonato';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.MOTIVO_MANCATO_RICONOSC IS 'Motivazione mancato riconoscimento della madre - Figlio abbandonato';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.FLG_PRIMO_FIGLIO IS 'Segnala se primo figlio per parto plurigemellare';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_SOGGETTO_INTERESSATO IS 'Soggetto interessato che ha richiesto trascrizione del proprio atto di nascita / Oppure Soggetto Riconsciuto/ Oppure Soggetto Comparente per SCelta Cognome.
QUANDO VIENE DEFINITO L''ATTO, IL NUOVO SOGGETTO CREATO NEL CASO PLURIGEMELLARE ASSUMERA'' CLONE DI QUANTO CREATO IN ANAGRAFE';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.CODICE_FAMIGLIA IS 'Codice Famiglia sleezionato per il Rapporto di parentela del Neonato';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_CODICE_LEGAME IS 'Legame di parentela del neonato con il Capofamiglia/Intestatario';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.RICON_FLG_ASSENSO_FIGLIO IS 'DEPRECATO - SPOSTATO SU ATTO_NASCITA; Assenso del figlio al riconoscimento';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.FLG_MAGGIORE_SCEGLIECOGNOME IS 'DEPRECATO - SPOSTATO SU ATTO_NASCITA; Figlio Maggiorebbe sceglie Cognome';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.FLG_ART33 IS 'DEPRECATO - SPOSTATO SU ATTO_NASCITA; Art.33';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.FLG_DISCONOSCIMENTO IS 'DEPRECATO - SPOSTATO SU ATTO_NASCITA; Disconoscimento';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.FLG_PROCURATORE_GENITORI IS 'DEPRECATO PER INUTILIZZO; Flag Procuratore PADRE/MADRE - non riportato sulla maschera ma nella tabella';

COMMENT ON COLUMN MATR_USR.ATTO_NASCITA_SOGGETTO.ID_CHECKBOX_COGNOME IS 'DEPRECATO - SPOSTATO SU ATTO_NASCITA; Scelta sul Cognome (1. Mantiene Cognome, 2. Aggiunge Cognome, 3. Sostituisce Cognome, 4. Antepone Cognome)';

