COMMENT ON TABLE MATR_USR.CFG_MAP_RULEAPP_FORMULA IS 'Tabella per censimento di tutte le associazioni tra RULEs di applicabilità e le FORMULE del FORMULARIO ATTI.
        FLG_MANDATORY=0 e FLG_AGGREGATE = 0 --- Se almeno una di queste RULEs è verificata la formula si applicata.
        FLG_MANDATORY=0 e FLG_AGGREGATE = 1 --- tutte queste RULEs devono essere verificate affinchè la formula si applichi.
        FLG_MANDATORY=1 e FLG_AGGREGATE = 0 --- Se verificata è AUTOSUFFICIENTE per abilitare la formula .
        FLG_MANDATORY=1 e FLG_AGGREGATE = 1 --- Deve essere verificata insieme a tutte le altre della stessa categoria per abilitare la formula.

Se non esiste alcuna RULE di applicabilità associata alla FORMULA, si assume di default sempre applicata se associata al modello.
   ';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULEAPP_FORMULA.ID_RULE IS 'Rule di applicabilità da associare alla FORMULA';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULEAPP_FORMULA.ID_FORMULA IS 'Formula a cui associare la rule di applicabilità';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULEAPP_FORMULA.FLG_MANDATORY IS 'Rule mandatory per abilitazione della formula - tutte le mandatory si verificano in AND per approvare la formula';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULEAPP_FORMULA.FLG_AGGREGATE IS 'Rule da verificare in aggregato (AND) alle altre per applicabilità, altrimenti autosufficiente (OR) se validata';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULEAPP_FORMULA.ID_RULE_GEN IS 'Rule di tipo GENERAZIONE da utilizzare nel caso sia verificata una RULE di applicabilità specifica (Ex. RULE per sottocasistiche)';



