  DATA_INIZIO_VALIDITA  DATE                    DEFAULT TO_DATE('01/01/1900','DD/MM/YYYY') NOT NULL,
  DATA_FINE_VALIDITA    DATE                    DEFAULT TO_DATE('31/12/2999','DD/MM/YYYY') NOT NULL,
  FLG_ENABLED           CHAR(1 BYTE)            DEFAULT 'S'                   NOT NULL,
  DATA_INS              TIMESTAMP(6)            DEFAULT SYSTIMESTAMP          NOT NULL,
  OPTIONAL1             VARCHAR2(256 BYTE),
  OPTIONAL2             VARCHAR2(256 BYTE),
  DATA_UPD              TIMESTAMP(6)            DEFAULT SYSTIMESTAMP          NOT NULL
)
