COMMENT ON TABLE MATR_USR.CFG_MAP_RULECTL_MODELLO IS 'Tabella per censimento di tutte le associazioni tra RULEs di controllo e i MODELLI DEGLI ATTI.
        FLG_MANDATORY=0 e FLG_AGGREGATE = 0 --- Se almeno una di queste RULEs è verificata la formula si applicata.
        FLG_MANDATORY=0 e FLG_AGGREGATE = 1 --- tutte queste RULEs devono essere verificate affinchè il controllo sia superato.
        FLG_MANDATORY=1 e FLG_AGGREGATE = 0 --- Se verificata è AUTOSUFFICIENTE per validare il controllo
        FLG_MANDATORY=1 e FLG_AGGREGATE = 1 --- Deve essere verificata insieme a tutte le altre della stessa categoria per validare il controllo.

Se non esiste alcuna RULE di controllo associato al MODELLO, si assume di default sempre controlli superati per il modello.
   ';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULECTL_MODELLO.ID_RULE IS 'Rule di applicabilità da associare alla FORMULA';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULECTL_MODELLO.ID_MODELLO_ATTO IS 'Modello a cui applicare la rule di controllo';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULECTL_MODELLO.AREA IS 'Area del Modello a cui applicare la rule di controllo';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULECTL_MODELLO.FLG_MANDATORY IS 'Rule mandatory per abilitazione della formula - tutte le mandatory si verificano in AND per approvare la formula';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULECTL_MODELLO.FLG_AGGREGATE IS 'Rule da verificare in aggregato (AND) alle altre per controllo, altrimenti autosufficiente (OR) se validata';



