COMMENT ON TABLE MATR_USR.CFG_MAP_RULEAPP_ANNOTA IS 'Tabella per censimento di tutte le associazioni tra RULEs di applicabilità e le MATRICI delle ANNOTAZIONI.
        FLG_MANDATORY=0 e FLG_AGGREGATE = 0 --- Se almeno una di queste RULEs è verificata la matrice si applicata.
        FLG_MANDATORY=0 e FLG_AGGREGATE = 1 --- tutte queste RULEs devono essere verificate affinchè la matrice si applichi.
        FLG_MANDATORY=1 e FLG_AGGREGATE = 0 --- Se verificata è AUTOSUFFICIENTE per abilitare la matrice .
        FLG_MANDATORY=1 e FLG_AGGREGATE = 1 --- Deve essere verificata insieme a tutte le altre della stessa categoria per abilitare la matrice.
   ';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULEAPP_ANNOTA.ID_RULE IS 'Rule di applicabilità da associare alla FORMULA';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULEAPP_ANNOTA.ID_MATRICE IS 'Matrice a cui associare la rule di applicabilità';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULEAPP_ANNOTA.FLG_MANDATORY IS 'Rule mandatory per abilitazione della formula - tutte le mandatory si verificano in AND per approvare la formula';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULEAPP_ANNOTA.FLG_AGGREGATE IS 'Rule da verificare in aggregato (AND) alle altre per applicabilità, altrimenti autosufficiente (OR) se validata';

COMMENT ON COLUMN MATR_USR.CFG_MAP_RULEAPP_ANNOTA.ID_RULE_GEN IS 'Rule di tipo GENERAZIONE da utilizzare nel caso sia verificata una RULE di applicabilità specifica (Ex. RULE per sottocasistiche)';



